/**
 * labDungeonData.js
 *
 * '미지의 소리 마을' 던전풍 맵 데이터 — mystery/Tiled_files/Dungeon1.tmx(Craftpix 던전 팩
 * 공식 샘플 맵)의 벽/바닥/물/창문/횃불/함정/오브젝트 레이어를 그대로 파싱해 게임 좌표계로
 * 옮긴 것. 자체 오토타일/방 배치를 새로 설계하지 않고 전문가가 만든 배치를 그대로
 * 재사용한다(사용자 확정).
 *
 * 원본 콘텐츠는 tx=2~39,ty=2~29(38×28)로 게임 맵(48×36)보다 좁아서 우측/하단이 빈
 * 갈색 바닥으로 남는 문제가 있었다. 최근접 이웃 리샘플링(nearest-neighbor upscale)으로
 * 48×36 각 칸이 원본의 대응 좌표(floor(newTx/Sx)+2, floor(newTy/Sy)+2, Sx=48/38,
 * Sy=36/28)에서 값을 가져와 원본 모양이 통째로 커진 것처럼 채운다.
 *
 * 벽/바닥/물(LAB_STATIC)은 반복 타일링돼도 안 보이는 배경 텍스처라 대상 칸 전부를
 * 채우지만, 문/횃불/함정/소품처럼 눈에 띄는 개별 오브젝트(LAB_TORCHES/TRAPS/PROPS)는
 * Sx,Sy가 정수가 아니라 원본 1칸이 대상 2칸에 겹쳐 매핑될 때가 있어 그대로 채우면
 * '문이 두 짝씩 겹쳐 보이는' 등 중복 배치 버그가 생겼다(사용자 스크린샷으로 확인) —
 * 그래서 이 세 카테고리는 같은 원본 오브젝트당 정확히 한 번만(처음 매핑되는 대상 칸에)
 * 배치하도록 리샘플링 시점에 중복 제거했다(사용자 확정).
 *
 * 좌표가 이미 48×36 정수 그리드라 별도 스케일 변환 없이 기존 tx*TILE 렌더링 방식을
 * 그대로 쓸 수 있고, spawnSoundItems가 쓰는 정수 타일 좌표와도 자동으로 정렬된다.
 *
 * 각 행 포맷:
 *   STATIC / TORCHES : [tx, ty, sheetCode, col, row, animLocalId(-1=없음)]
 *   TRAPS / PROPS    : [tx, ty, sheetCode, col, row]  (항상 idle 프레임 그대로 표시)
 * sheetCode → SHEET_CODES 인덱스. animLocalId가 있으면 ANIM[sheetCode][animLocalId]에서
 * 프레임 목록([col,row,durationMs])을 찾아 시간 기반으로 순환 재생한다.
 */

export const LAB_DUNGEON_W = 48
export const LAB_DUNGEON_H = 36

export const SHEET_CODES = ["wallsFloor", "crackedWalls", "crackedFloor", "waterCoasts", "waterDetail", "crackedCoasts", "fire1", "fire2", "doorsLeverChest", "objects", "trap"]

